"""Generate a standalone browser dashboard from actual pipeline outputs."""
import json
from pathlib import Path
import pandas as pd
ROOT=Path(__file__).resolve().parent
OUT=ROOT/'outputs'
metrics=json.loads((OUT/'metrics.json').read_text())
risk=pd.read_csv(OUT/'risk_transactions.csv')
quality=pd.read_csv(OUT/'quality_results.csv')
exceptions=pd.read_csv(OUT/'exceptions.csv').fillna('')
data={'metrics':metrics,'categories':risk.groupby('merchant_category').amount.sum().to_dict(),'rules':quality.to_dict('records'),'exceptions':exceptions.to_dict('records'),'reviews':risk.loc[risk.risk_status.eq('Review'),['transaction_id','customer_id','amount','merchant_category','timestamp','purchases_60m','high_value','rapid_activity']].sort_values('amount',ascending=False).to_dict('records')}
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FinGuard | Governance & risk</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef3f6;color:#193247;font:15px system-ui,sans-serif}header{background:#12334a;color:white;padding:28px max(20px,calc((100% - 1160px)/2));}header h1{margin:5px 0;font-size:30px}header p{color:#c5d8e0;margin:6px 0}.eyebrow{font-size:12px;letter-spacing:2px;color:#7bddd1;font-weight:700}main{max-width:1160px;margin:auto;padding:22px 16px 40px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.card,section{background:white;border:1px solid #dce5ea;border-radius:12px;padding:18px}.card strong{display:block;font-size:30px;margin-top:8px}.card small,small{color:#587082}section{margin-top:15px}h2{font-size:20px;margin:0 0 12px}p{line-height:1.5}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:15px}.bar{display:grid;grid-template-columns:110px 1fr 92px;align-items:center;gap:8px;margin:12px 0;font-size:13px}.track{background:#e5edf0;border-radius:4px;height:12px;overflow:hidden}.fill{height:100%;background:#087f78}.amber{background:#c27b20}.scroll{overflow:auto;max-height:340px}table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th,td{text-align:left;padding:10px;border-bottom:1px solid #e4ebef}th{background:#f0f5f7;position:sticky;top:0}select{padding:8px;border:1px solid #a8bdc8;border-radius:6px;color:#193247;background:white}label{font-weight:600;margin-right:8px}.note{border-left:3px solid #087f78;padding-left:10px}footer{color:#587082;font-size:12px;padding-top:20px}button{border:0;border-radius:6px;background:#087f78;color:white;padding:9px 12px;cursor:pointer} @media(max-width:600px){header h1{font-size:23px}.bar{grid-template-columns:95px 1fr 75px}.card strong{font-size:24px}}
</style><header><div class="eyebrow">FINGUARD / PORTFOLIO DEMO</div><h1>Financial data governance &amp; risk analytics</h1><p>Synthetic transactions · Interactive local snapshot · No real customer data</p></header><main><div class="cards" id="cards"></div><div class="grid"><section><h2>Data quality failures</h2><small>Number of failed records per rule</small><div id="rules"></div></section><section><h2>Accepted purchase value</h2><small>INR by merchant category</small><div id="categories"></div></section></div><section><h2>Exception queue</h2><label for="rule">Rule</label><select id="rule"></select> <button id="export">Export filtered CSV</button><p id="ecount"></p><div class="scroll"><table id="exceptions"></table></div></section><section><h2>Risk review queue</h2><p class="note">High value &gt; ₹50,000 or at least 3 accepted purchases in 60 minutes. Review flags are not proof of fraud.</p><label for="risk">Filter</label><select id="risk"><option>All review flags</option><option>High value</option><option>Rapid activity</option></select><p id="rcount"></p><div class="scroll"><table id="reviews"></table></div></section><section><h2>Governance and lineage</h2><p>Raw synthetic CSV → Python quality rules → accepted masked records / exception references → SQLite risk SQL → dashboard. Optional BigQuery batch upload is separate.</p><p>Proposed owner: transaction data product owner. Steward: data quality analyst. Emails are removed from processed files; customer IDs remain pseudonymous.</p><small id="audit"></small></section><footer>Offline snapshot generated from the included pipeline. Refresh with python build_preview.py. Not a production risk system or an American Express product.</footer></main><script>
const D=__DATA__;const $=id=>document.getElementById(id);const fmt=n=>Number(n).toLocaleString('en-IN');const m=D.metrics;
function el(tag,txt){let e=document.createElement(tag);e.textContent=txt;return e;}
for(const [label,v] of [['Input records',fmt(m.input_rows)],['Accepted',fmt(m.accepted_rows)],['Rejected',fmt(m.rejected_rows)],['Acceptance rate',m.acceptance_pct+'%'],['Risk review',fmt(m.review_rows)]]){let c=el('div','');c.className='card';c.append(el('small',label),el('strong',v));$('cards').append(c);}
function bars(id,pairs,kind){let max=Math.max(1,...pairs.map(p=>p[1]));for(const [name,value] of pairs){let row=el('div','');row.className='bar';let track=el('div','');track.className='track';let fill=el('div','');fill.className='fill '+(kind==='rule'?'amber':'');fill.style.width=100*value/max+'%';track.append(fill);row.append(el('span',name),track,el('span',kind==='rule'?fmt(value):'₹'+fmt(value)));$(id).append(row);}}
bars('rules',D.rules.map(x=>[x.rule_id,x.failed_rows]),'rule');bars('categories',Object.entries(D.categories),'money');
function table(id,rows,keys){let t=$(id);t.replaceChildren();let h=el('tr','');for(let k of keys)h.append(el('th',k.replaceAll('_',' ')));let head=el('thead','');head.append(h);t.append(head);let body=el('tbody','');for(let r of rows){let tr=el('tr','');for(let k of keys)tr.append(el('td',r[k]??''));body.append(tr);}t.append(body);}
for(let name of ['All',...D.rules.map(x=>x.rule_id)])$('rule').append(el('option',name));
function exceptions(){let v=$('rule').value;return D.exceptions.filter(x=>v==='All'||x.failed_rules.split('|').includes(v));}
function showE(){let r=exceptions();$('ecount').textContent=fmt(r.length)+' matching exception records';table('exceptions',r,['source_row','transaction_id','failed_rules']);}
function showR(){let v=$('risk').value;let r=D.reviews.filter(x=>v==='All review flags'||(v==='High value'?x.high_value:x.rapid_activity));$('rcount').textContent=fmt(r.length)+' matching review records';table('reviews',r,['transaction_id','customer_id','amount','merchant_category','timestamp','purchases_60m']);}
$('rule').onchange=showE;$('risk').onchange=showR;showE();showR();$('audit').textContent='Run '+m.run_id+' | '+m.processed_at_utc+' | Rules '+m.rules_version+' | Source SHA-256 '+m.input_sha256;
$('export').onclick=()=>{let keys=['source_row','transaction_id','failed_rules'];let rows=[keys,...exceptions().map(r=>keys.map(k=>r[k]??''))];let csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));let a=el('a','');a.href=url;a.download='exceptions.csv';a.click();URL.revokeObjectURL(url);};
</script></html>'''
(ROOT/'dashboard_preview.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
print('Created dashboard_preview.html')
